-- Applied to bakedCRM on 2026-11-23 (Phase 2). Prices are placeholders.
-- Archive the 70 generic seed items (kept, hidden, not orderable)
update public.products set archived_at = now(), is_visible = false, is_active = false where archived_at is null and is_placeholder = false;

-- Categories shared by both brands
on conflict (name) do update set subtitle = excluded.subtitle, subtitle_tsismis = excluded.subtitle_tsismis, sort_order = excluded.sort_order, brand_id = null;

